import org.deeptimeline.app.LabelGeometry
import org.deeptimeline.app.LabelSolver
import kotlin.math.abs
fun main(){val anchors=doubleArrayOf(-1500.0,-12.0,-10.0,-8.0,-6.0,-4.0,1500.0);var previousGap=0.0;for(scale in listOf(0.85f,1f,1.3f,1.7f,2f,2.5f,3f)){val ascent=-15f*scale;val descent=4f*scale;val leading=1f*scale;val spacing=20f*scale;val gap=LabelGeometry.gap(ascent,descent,leading,spacing,3f);check(gap>previousGap);previousGap=gap;val halfHit=LabelGeometry.hitRadius(ascent,descent,3f);check(halfHit>0.0);val offset=LabelGeometry.baselineOffset(ascent,descent);check(abs(offset-(11f*scale/2f))<0.0001f);val result=LabelSolver.solve(anchors,gap,0.0);for(i in 1 until result.size)check(result[i]-result[i-1]>=gap-1e-7){"Overlap at fontScale $scale"};check(abs(result[0]-anchors[0])<1e-7&&abs(result[6]-anchors[6])<1e-7){"Independent events bent at fontScale $scale"};val visible=LabelGeometry.visibleMargin(ascent,descent);check(visible>=15f*scale)};println("Font metrics: scaled spacing, selection radius, baseline, offscreen culling, and hyperflow across font sizes: PASS")}
